rule_difference : ∀ {T : Type} [inst : Lax392996.Databases.ValueType T] {K : Type} {n : Nat}
  (q₁ q₂ : Lax392996.RelationalAlgebra.Query T n) (hq : (q₁.Diff q₂).source),
  Eq (Lax392996.RewritingRules.Query.rewriting (q₁.Diff q₂) hq)
    (let q'₁ := Lax392996.RewritingRules.Query.rewriting q₁ ⋯;
    let q'₂ := Lax392996.RewritingRules.Query.rewriting q₂ ⋯;
    let joinCond₁ :=
      List.foldr (fun t t' => t.And t') Lax392996.RelationalAlgebra.Selection.True
        (List.map
          (fun j =>
            Lax392996.RelationalAlgebra.Selection.BT
              (Lax392996.RelationalAlgebra.BoolTerm.EQ
                (Lax392996.RelationalAlgebra.Term.index (Fin.ofNat (instHAdd.hAdd (instHMul.hMul 2 n) 1) j))
                (Lax392996.RelationalAlgebra.Term.index
                  (Fin.ofNat (instHAdd.hAdd (instHMul.hMul 2 n) 1) (instHAdd.hAdd (instHAdd.hAdd j n) 1)))))
          (List.range n));
    let prod₁t := fun r => Lax392996.RelationalAlgebra.Query.Sel joinCond₁ (q'₁.Prod r);
    let prod₁r :=
      ((Lax392996.RelationalAlgebra.Query.Proj (fun j => Lax392996.RelationalAlgebra.Term.index (Fin.castLE ⋯ j))
              q'₁).Diff
          (Lax392996.RelationalAlgebra.Query.Proj (fun j => Lax392996.RelationalAlgebra.Term.index (Fin.castLE ⋯ j))
            q'₂)).Dedup;
    let prod₁ := prod₁t prod₁r;
    let joinCond₂ :=
      List.foldr (fun t t' => t.And t') Lax392996.RelationalAlgebra.Selection.True
        (List.map
          (fun j =>
            Lax392996.RelationalAlgebra.Selection.BT
              (Lax392996.RelationalAlgebra.BoolTerm.EQ
                (Lax392996.RelationalAlgebra.Term.index (Fin.ofNat (instHAdd.hAdd (instHMul.hMul 2 n) 2) j))
                (Lax392996.RelationalAlgebra.Term.index
                  (Fin.ofNat (instHAdd.hAdd (instHMul.hMul 2 n) 2) (instHAdd.hAdd (instHAdd.hAdd j n) 1)))))
          (List.range n));
    let prod₂t := fun r => Lax392996.RelationalAlgebra.Query.Sel joinCond₂ (q'₁.Prod r);
    let prod₂r :=
      Lax392996.RelationalAlgebra.Query.ProvSum (fun j => Fin.castLE ⋯ j)
        (Lax392996.RelationalAlgebra.Term.index (Fin.last n)) q'₂;
    let prod₂ := prod₂t prod₂r;
    let ts₁ := fun j => Lax392996.RelationalAlgebra.Term.index (Fin.castLE ⋯ j);
    let ts₂ := fun j =>
      ite (instLTNat.lt j.val n) (Lax392996.RelationalAlgebra.Term.index (Fin.castLE ⋯ j))
        ((Lax392996.RelationalAlgebra.Term.index
              (Fin.ofNat (instHAdd.hAdd (instHAdd.hAdd (instHMul.hMul 2 n) 1) 1) n)).sub
          (Lax392996.RelationalAlgebra.Term.index (Fin.last (instHAdd.hAdd (instHMul.hMul 2 n) 1))));
    (Lax392996.RelationalAlgebra.Query.Proj ts₁ prod₁).Sum (Lax392996.RelationalAlgebra.Query.Proj ts₂ prod₂))
